import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_SIZE = 410;
    static final int MAX_EDGES = 200020;
    static final int INF = 0x3f3f3f3f;
    static final int[][] directions = {{-1,0},{0,1},{1,0},{0,-1}};
    static int[][] distMap = new int[12][12];
    static int[][] timeMap = new int[12][12];
    static char[][] grid;
    static char[][] heat;
    static int n, t;
    static MaxFlowImplementation maxFlowSolver = new MaxFlowImplementation();

    static class MaxFlowImplementation {
        int[] head = new int[MAX_SIZE], v = new int[MAX_EDGES], nxt = new int[MAX_EDGES], capacity = new int[MAX_EDGES], flow = new int[MAX_EDGES];
        int[] current = new int[MAX_SIZE], dist = new int[MAX_SIZE];
        int s, t, edgeCount;

        void init() {
            Arrays.fill(head, -1);
            edgeCount = 0;
        }

        void addEdge(int u, int v, int c) {
            this.v[edgeCount] = v;
            this.nxt[edgeCount] = head[u];
            this.capacity[edgeCount] = c;
            this.flow[edgeCount] = 0;
            head[u] = edgeCount++;
            this.v[edgeCount] = u;
            this.nxt[edgeCount] = head[v];
            this.capacity[edgeCount] = 0;
            this.flow[edgeCount] = 0;
            head[v] = edgeCount++;
        }

        boolean buildLevelGraph() {
            Arrays.fill(dist, -1);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = head[u]; i != -1; i = nxt[i]) {
                    int v = this.v[i];
                    if (dist[v] == -1 && capacity[i] > flow[i]) {
                        dist[v] = dist[u] + 1;
                        q.offer(v);
                    }
                }
            }
            return dist[t] != -1;
        }

        int sendFlow(int u, int flowIn) {
            if (u == t || flowIn == 0) return flowIn;
            int totalFlow = 0, pushed;
            for (int i = current[u]; i != -1; i = nxt[i]) {
                int v = this.v[i];
                if (dist[v] == dist[u] + 1 && (pushed = sendFlow(v, Math.min(flowIn, capacity[i] - flow[i]))) > 0) {
                    flow[i] += pushed;
                    flow[i ^ 1] -= pushed;
                    flowIn -= pushed;
                    totalFlow += pushed;
                    if (flowIn == 0) break;
                }
            }
            return totalFlow;
        }

        int maxFlow(int s, int t) {
            this.s = s;
            this.t = t;
            int total = 0;
            while (buildLevelGraph()) {
                System.arraycopy(head, 0, current, 0, head.length);
                total += sendFlow(s, INF);
            }
            return total;
        }
    }

    static int readNumber(BufferedReader br, StringTokenizer st) throws IOException {
        return Integer.parseInt(st.nextToken());
    }

    static char readLetter(BufferedReader br, StringTokenizer st) throws IOException {
        String s = st.nextToken();
        return s.charAt(0);
    }

    static boolean valid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    static void findObstacles(int sx, int sy) {
        for (int i = 0; i < n; i++) {
            Arrays.fill(timeMap[i], 0x3f);
        }
        Queue<Integer> q = new LinkedList<>();
        q.offer(sx * 10 + sy);
        timeMap[sx][sy] = 0;
        while (!q.isEmpty()) {
            int front = q.poll();
            int x = front / 10;
            int y = front % 10;
            for (int[] dir : directions) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (valid(nx, ny) && grid[nx][ny] >= '0' && grid[nx][ny] <= '9' && timeMap[nx][ny] > timeMap[x][y] + 1) {
                    timeMap[nx][ny] = timeMap[x][y] + 1;
                    q.offer(nx * 10 + ny);
                }
            }
        }
    }

    static void findHeatSources(int sx, int sy) {
        for (int i = 0; i < n; i++) {
            Arrays.fill(distMap[i], 0x3f);
        }
        Queue<Integer> q = new LinkedList<>();
        q.offer(sx * 10 + sy);
        distMap[sx][sy] = 0;
        while (!q.isEmpty()) {
            int front = q.poll();
            int x = front / 10;
            int y = front % 10;
            for (int[] dir : directions) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (valid(nx, ny) && heat[nx][ny] >= '0' && heat[nx][ny] <= '9' && distMap[nx][ny] > distMap[x][y] + 1) {
                    if (heat[nx][ny] >= '0' && timeMap[nx][ny] >= distMap[x][y] + 1) {
                        distMap[nx][ny] = distMap[x][y] + 1;
                        if (timeMap[nx][ny] > distMap[nx][ny]) {
                            q.offer(nx * 10 + ny);
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        grid = new char[n][n];
        heat = new char[n][n];

        for (int i = 0; i < n; i++) {
            grid[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            heat[i] = br.readLine().toCharArray();
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'Z') {
                    findObstacles(i, j);
                }
            }
        }

        int S = 0;
        int T = n * n * 2 + 1;
        maxFlowSolver.init();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > '0' && grid[i][j] <= '9') {
                    maxFlowSolver.addEdge(S, i * n + j + 1, grid[i][j] - '0');
                }
                if (heat[i][j] > '0' && heat[i][j] <= '9') {
                    maxFlowSolver.addEdge(n * n + i * n + j + 1, T, heat[i][j] - '0');
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > '0' && grid[i][j] <= '9') {
                    findHeatSources(i, j);
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (heat[x][y] > '0' && heat[x][y] <= '9' && distMap[x][y] <= t) {
                                maxFlowSolver.addEdge(i * n + j + 1, n * n + x * n + y + 1, INF);
                            }
                        }
                    }
                }
            }
        }

        int res = maxFlowSolver.maxFlow(S, T);
        System.out.println(res);
    }
}
